window.RP_SESSION={"id":"S-04ebef986aec","messages":[{"id":"RP-0214554","time":"2026-08-05T02:25:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"결국 일어난 세드릭","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214555","time":"2026-08-05T02:25:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“음… 배고프다.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214556","time":"2026-08-05T02:25:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"부엌으로 가봅니다. 적당한 식재료들을 모아다가 썰고 섞고… 슉슉…","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214557","time":"2026-08-05T02:25:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214558","time":"2026-08-05T02:25:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'세드릭'의 민첩 판정 :\n[2] + [2] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0214559","time":"2026-08-05T02:26:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"”에잎, 퉤. 어으 흙 씹었어.“","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214560","time":"2026-08-05T02:27:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"앞으로는 음식을 잘 씻어야겠군요…","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214561","time":"2026-08-05T02:27:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"여튼, 그렇게 사치스럽게도 야식을 퍼먹으며, 세드릭은 생각에 잠깁니다.","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214562","time":"2026-08-05T02:28:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"”…살아있을까.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214563","time":"2026-08-05T02:28:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“그래도… 꽤나 부잣집이었는데. 실력 있는 의사들도 엄청 불렀을 거고.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214564","time":"2026-08-05T02:29:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“무엇보다… 짐덩어리인 내가 사라져줬으니…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214565","time":"2026-08-05T02:29:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“그 대가로라도, 행복했으면 좋겠는데.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214566","time":"2026-08-05T02:31:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“어디 멀끔한 부잣집 도련님 만나서, 결혼하고, 아이도 생기고. 그렇게… 평범하고 행복하게.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214567","time":"2026-08-05T02:31:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“에잉, 쯧. 술 없나.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214568","time":"2026-08-05T02:32:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214569","time":"2026-08-05T02:32:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 4 = 4\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-0214570","time":"2026-08-05T02:32:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"”아니, 맥주를… 누가 다 거덜냈지..?“","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214571","time":"2026-08-05T02:33:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"뭐, 심란할 때 마셔봐야 기분만 더 울적해질테죠.","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214572","time":"2026-08-05T02:35:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"순돌이… 쓰담쓰담…","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214573","time":"2026-08-05T02:35:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“하아… 나도 안다고… 돌멩이랑 노는 게 이상해보이\n는 건…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214574","time":"2026-08-05T02:38:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"식기를 물에 헹구고…","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214575","time":"2026-08-05T02:38:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"뽀득뽀득…","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214576","time":"2026-08-05T02:38:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"”휴, 이제…“","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214577","time":"2026-08-05T02:39:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“뭐야, 저 분들 아직도 안 주무시네. 뭐가 그리 재밌길래…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214578","time":"2026-08-05T02:39:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“쓰으읍… 아냐, 내 주제에…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214579","time":"2026-08-05T02:40:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“하씨 그래도 같은 길드원인데 쫄 필요는…!”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214580","time":"2026-08-05T02:40:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“하아 근데 또 쫄리는 건 어쩔 수 없고…”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214581","time":"2026-08-05T02:41:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"“… 에잇.”","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214582","time":"2026-08-05T02:41:00+09:00","room":"RP","name":"세드릭","profile":"세드릭","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-4b8d7bf3c420"]},{"id":"RP-0214583","time":"2026-08-05T02:41:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-0214584","time":"2026-08-05T03:17:00+09:00","room":"RP","name":"페트라","profile":"페트라","identity":"unresolved","type":"dialogue","body":"이모티콘","characters":[]}]};
